// 1. Fetch data from the HTTP Request node by its exact name
const httpRequestData = $('Get All Items in LDR Ready Folder').all();
// Extract the drive items array from the nested value property
const httpDriveItems = httpRequestData[0]?.json?.value || [];

// 2. Fetch data from the Data Table node by its exact name
const dataTableData = $('Get All Rows in Data Table').all();

// 3. Create a Set of existing file IDs from the Data Table
const existingFileIds = new Set(
  dataTableData.map(item => item.json.fileID)
);

// 4. Filter HTTP items whose 'id' does not exist in the Data Table
const missingItems = httpDriveItems.filter(item => !existingFileIds.has(item.id));

// 5. Output filtered items in n8n format
return missingItems.map(item => ({ json: item }));

const items = $input.all();

/**
 * ============================================================
 * HALPERN LDR NORMALIZER
 * ============================================================
 *
 * Purpose:
 * 1. Normalize values coming from any of the Edit Fields nodes.
 * 2. Build wholeTerm_Calc[] from the year-by-year rent fields.
 * 3. Remove the original tableCalc_*yearX fields.
 * 4. Add template-friendly conditional flags.
 * 5. Add formatted display values without destroying raw values.
 * 6. Support both normal date strings and Excel serial dates.
 *
 * Recommended n8n Code Node mode:
 * "Run Once for All Items"
 */


/**
 * ============================================================
 * BASIC HELPERS
 * ============================================================
 */


/**
 * Returns true only for values that should be treated as absent.
 *
 * IMPORTANT:
 * false is NOT empty.
 * 0 is NOT universally empty because some LDR fields may
 * legitimately contain zero.
 */
function isBlank(value) {
	return (
		value === null ||
		value === undefined ||
		(typeof value === 'string' && value.trim() === '')
	);
}


/**
 * Used specifically for unused rent-table rows.
 *
 * The current LDR sends unused years as:
 * psf = 0
 * monthly = 0
 * annual = 0
 *
 * So zero is considered empty for rent rows only.
 */
function isEmptyRentValue(value) {
	return (
		value === null ||
		value === undefined ||
		value === '' ||
		Number(value) === 0
	);
}


/**
 * Normalize YES/NO style fields to booleans.
 */
function isYes(value) {
	if (typeof value === 'boolean') {
		return value;
	}

	if (value === null || value === undefined) {
		return false;
	}

	const normalized = String(value)
		.trim()
		.toUpperCase();

	return ['YES', 'Y', 'TRUE', '1'].includes(normalized);
}


/**
 * ============================================================
 * NUMBER / CURRENCY HELPERS
 * ============================================================
 */


/**
 * Currency display helper.
 */
function formatCurrency(value) {
	if (isBlank(value)) {
		return null;
	}

	const number = Number(value);

	if (!Number.isFinite(number)) {
		return null;
	}

	return number.toLocaleString('en-US', {
		style: 'currency',
		currency: 'USD',
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	});
}


/**
 * Number display helper.
 */
function formatNumber(value, decimals = 2) {
	if (isBlank(value)) {
		return null;
	}

	const number = Number(value);

	if (!Number.isFinite(number)) {
		return null;
	}

	return number.toLocaleString('en-US', {
		minimumFractionDigits: decimals,
		maximumFractionDigits: decimals,
	});
}


/**
 * Square-foot display helper.
 */
function formatSquareFeet(value) {
	if (isBlank(value)) {
		return null;
	}

	const number = Number(value);

	if (!Number.isFinite(number)) {
		return null;
	}

	return number.toLocaleString('en-US', {
		maximumFractionDigits: 0,
	});
}


/**
 * Format rent values.
 */
function formatRent(value) {
	return formatCurrency(value);
}


/**
 * ============================================================
 * DATE HELPERS
 * ============================================================
 */


/**
 * Parse:
 *
 * - Excel serial dates:
 *      46266
 *      "46266"
 *
 * - Normal US dates:
 *      9/1/2026
 *      09/01/2026
 *
 * - ISO dates:
 *      2026-09-01
 *
 * Returns a Date object or null.
 */
function parseDate(value) {
	if (isBlank(value)) {
		return null;
	}

	const raw = String(value).trim();


	/**
	 * --------------------------------------------------------
	 * EXCEL SERIAL DATE
	 * --------------------------------------------------------
	 *
	 * Example:
	 * 46266 -> September 1, 2026
	 *
	 * Excel's standard Windows date system is represented here
	 * using 1899-12-30 as the effective epoch.
	 */
	if (/^\d+(\.\d+)?$/.test(raw)) {

		const serial = Number(raw);

		/**
		 * Restrict serial detection to a reasonable date range.
		 * This prevents values like "5" or "1500" from being
		 * accidentally interpreted as Excel dates.
		 */
		if (
			Number.isFinite(serial) &&
			serial >= 20000 &&
			serial <= 100000
		) {
			const excelEpoch = Date.UTC(1899, 11, 30);

			const milliseconds =
				serial * 24 * 60 * 60 * 1000;

			return new Date(
				excelEpoch + milliseconds
			);
		}
	}


	/**
	 * --------------------------------------------------------
	 * MM/DD/YYYY OR M/D/YYYY
	 * --------------------------------------------------------
	 *
	 * Parse manually to avoid JavaScript/environment ambiguity.
	 */
	const usDateMatch =
		raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

	if (usDateMatch) {

		const month = Number(usDateMatch[1]);
		const day = Number(usDateMatch[2]);
		const year = Number(usDateMatch[3]);

		const date = new Date(
			Date.UTC(year, month - 1, day)
		);

		if (!Number.isNaN(date.getTime())) {
			return date;
		}
	}


	/**
	 * --------------------------------------------------------
	 * ISO YYYY-MM-DD
	 * --------------------------------------------------------
	 */
	const isoDateMatch =
		raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);

	if (isoDateMatch) {

		const year = Number(isoDateMatch[1]);
		const month = Number(isoDateMatch[2]);
		const day = Number(isoDateMatch[3]);

		const date = new Date(
			Date.UTC(year, month - 1, day)
		);

		if (!Number.isNaN(date.getTime())) {
			return date;
		}
	}


	/**
	 * --------------------------------------------------------
	 * FALLBACK
	 * --------------------------------------------------------
	 */
	const date = new Date(raw);

	if (Number.isNaN(date.getTime())) {
		return null;
	}

	return date;
}


/**
 * Convert any supported date into:
 *
 * SEPTEMBER 1, 2026
 */
function formatDateLong(value) {
	const date = parseDate(value);

	if (!date) {
		return isBlank(value)
			? null
			: String(value).trim();
	}

	return date
		.toLocaleDateString('en-US', {
			month: 'long',
			day: 'numeric',
			year: 'numeric',
			timeZone: 'UTC',
		})
		.toUpperCase();
}


/**
 * Convert a date's day into an ordinal.
 *
 * Examples:
 * 1  -> 1ST
 * 2  -> 2ND
 * 3  -> 3RD
 * 4  -> 4TH
 * 11 -> 11TH
 * 12 -> 12TH
 * 13 -> 13TH
 * 21 -> 21ST
 */
function formatOrdinalDay(value) {
	const date = parseDate(value);

	if (!date) {
		return null;
	}

	const day = date.getUTCDate();
	const mod100 = day % 100;

	let suffix = 'TH';

	if (mod100 < 11 || mod100 > 13) {

		switch (day % 10) {

			case 1:
				suffix = 'ST';
				break;

			case 2:
				suffix = 'ND';
				break;

			case 3:
				suffix = 'RD';
				break;
		}
	}

	return `${day}${suffix}`;
}


/**
 * Convert any supported date into:
 *
 * SEPTEMBER 2026
 */
function formatMonthYear(value) {
	const date = parseDate(value);

	if (!date) {
		return null;
	}

	return date
		.toLocaleDateString('en-US', {
			month: 'long',
			year: 'numeric',
			timeZone: 'UTC',
		})
		.toUpperCase();
}


/**
 * Format an already-created Date object as:
 *
 * MM/DD/YYYY
 *
 * Used primarily by wholeTerm_Calc.
 */
function formatDateShort(date) {
	if (
		!(date instanceof Date) ||
		Number.isNaN(date.getTime())
	) {
		return null;
	}

	const month =
		String(date.getUTCMonth() + 1)
			.padStart(2, '0');

	const day =
		String(date.getUTCDate())
			.padStart(2, '0');

	const year =
		date.getUTCFullYear();

	return `${month}/${day}/${year}`;
}


/**
 * Normalize an incoming raw date to:
 *
 * M/D/YYYY
 *
 * Examples:
 *
 * 46266
 *      -> 9/1/2026
 *
 * "09/01/2026"
 *      -> 9/1/2026
 */
function normalizeRawDate(value) {
	const date = parseDate(value);

	if (!date) {
		return isBlank(value)
			? ''
			: String(value).trim();
	}

	const month =
		date.getUTCMonth() + 1;

	const day =
		date.getUTCDate();

	const year =
		date.getUTCFullYear();

	return `${month}/${day}/${year}`;
}


/**
 * ============================================================
 * WHOLE-TERM DATE RANGE HELPER
 * ============================================================
 *
 * Rules:
 *
 * First rent row:
 * - Starts on newLRA_leaseStartDate
 * - Ends December 31 of that calendar year
 * - Unless the lease itself ends during that same year
 *
 * Middle rent rows:
 * - January 1
 * - December 31
 *
 * Last rent row:
 * - Ends on newLRA_leaseEndDate
 */
function getLeaseYearDateRange(
	leaseStartValue,
	leaseEndValue,
	rowIndex,
	totalRows
) {
	const leaseStart =
		parseDate(leaseStartValue);

	const leaseEnd =
		parseDate(leaseEndValue);


	if (
		!leaseStart ||
		!leaseEnd ||
		totalRows <= 0
	) {
		return {
			yearStartDate: null,
			yearEndDate: null,
		};
	}


	const leaseStartYear =
		leaseStart.getUTCFullYear();

	const leaseEndYear =
		leaseEnd.getUTCFullYear();

	const currentYear =
		leaseStartYear + rowIndex;


	let yearStartDate;
	let yearEndDate;


	/**
	 * --------------------------------------------------------
	 * START DATE
	 * --------------------------------------------------------
	 */

	if (rowIndex === 0) {

		yearStartDate =
			leaseStart;

	} else {

		yearStartDate =
			new Date(
				Date.UTC(
					currentYear,
					0,
					1
				)
			);
	}


	/**
	 * --------------------------------------------------------
	 * END DATE
	 * --------------------------------------------------------
	 */


	/**
	 * Lease begins and ends in same calendar year.
	 */
	if (
		rowIndex === 0 &&
		leaseStartYear === leaseEndYear
	) {

		yearEndDate =
			leaseEnd;

	}


	/**
	 * Final rent row always uses actual lease end date.
	 */
	else if (
		rowIndex === totalRows - 1
	) {

		yearEndDate =
			leaseEnd;

	}


	/**
	 * Normal calendar-year row.
	 */
	else {

		yearEndDate =
			new Date(
				Date.UTC(
					currentYear,
					11,
					31
				)
			);
	}


	return {
		yearStartDate:
			formatDateShort(yearStartDate),

		yearEndDate:
			formatDateShort(yearEndDate),
	};
}


/**
 * ============================================================
 * PROCESS EVERY INPUT ITEM
 * ============================================================
 */

return items.map((item, itemIndex) => {

	const source = item.json;


	/**
	 * ========================================================
	 * 1. COPY NORMAL FIELDS
	 * ========================================================
	 *
	 * Exclude raw tableCalc_*yearX values because they will
	 * become wholeTerm_Calc[] below.
	 */

	const normalized = {};


	for (const [key, value] of Object.entries(source)) {

		const isWholeTermRentField =
			/^tableCalc_(PSF|MonthlyBaseRent|AnnualBaseRent)year\d+$/
				.test(key);


		if (isWholeTermRentField) {
			continue;
		}


		normalized[key] = value;
	}


	/**
	 * ========================================================
	 * 2. BUILD WHOLE TERM RENT ARRAY
	 * ========================================================
	 */

	const wholeTerm_Calc = [];


	const requestedYears =
		Number(source.rent_yearsInTerm);


	const maxYears =
		Number.isFinite(requestedYears) &&
		requestedYears > 0
			? Math.min(requestedYears, 10)
			: 10;


	for (
		let year = 1;
		year <= maxYears;
		year++
	) {

		const psf =
			source[`tableCalc_PSFyear${year}`];


		const monthlyBaseRent =
			source[
				`tableCalc_MonthlyBaseRentyear${year}`
			];


		const annualBaseRent =
			source[
				`tableCalc_AnnualBaseRentyear${year}`
			];


		/**
		 * Skip year only when ALL three rent values
		 * are empty / zero.
		 */
		if (
			isEmptyRentValue(psf) &&
			isEmptyRentValue(monthlyBaseRent) &&
			isEmptyRentValue(annualBaseRent)
		) {
			continue;
		}


		wholeTerm_Calc.push({

			year,


			/**
			 * Raw numeric values
			 */
			psf:
				isBlank(psf)
					? null
					: Number(psf),


			monthly_base_rent:
				isBlank(monthlyBaseRent)
					? null
					: Number(monthlyBaseRent),


			annual_base_rent:
				isBlank(annualBaseRent)
					? null
					: Number(annualBaseRent),


			/**
			 * Word/template display values
			 */
			psf_formatted:
				formatNumber(psf, 2),


			monthly_base_rent_formatted:
				formatRent(monthlyBaseRent),


			annual_base_rent_formatted:
				formatRent(annualBaseRent),
		});
	}


	/**
	 * --------------------------------------------------------
	 * ADD START / END DATE TO EACH RENT ROW
	 * --------------------------------------------------------
	 */

	wholeTerm_Calc.forEach(
		(rentRow, index) => {

			const dateRange =
				getLeaseYearDateRange(
					source.newLRA_leaseStartDate,
					source.newLRA_leaseEndDate,
					index,
					wholeTerm_Calc.length
				);


			rentRow.yearStartDate =
				dateRange.yearStartDate;


			rentRow.yearEndDate =
				dateRange.yearEndDate;
		}
	);


	normalized.wholeTerm_Calc =
		wholeTerm_Calc;


	normalized.wholeTerm_Calc_count =
		wholeTerm_Calc.length;


	/**
	 * ========================================================
	 * 3. TEMPLATE CONDITIONAL FLAGS
	 * ========================================================
	 */


	/**
	 * OPTION PERIOD
	 */
	const numberOfOptions =
		Number(source.newLRA_numNewOptions) || 0;


	const yearsPerOption =
		Number(source.newLRA_yearPerOption) || 0;


	normalized.has_option =
		numberOfOptions > 0 &&
		yearsPerOption > 0;


	/**
	 * WAIVED RENT
	 */
	normalized.include_waived_rent =
		isYes(source.lastNote_Waived_Rent);


	/**
	 * BROKERAGE
	 */
	normalized.has_tenant_broker =
		!isBlank(source.tenant_broker);


	normalized.has_halpern_broker =
		!isBlank(source.halpern_broker);


	normalized.has_broker =
		normalized.has_tenant_broker ||
		normalized.has_halpern_broker;


	/**
	 * SALES REPORT
	 *
	 * exclude_annual_sales_report = true
	 * means include_sales_report = false.
	 */
	if (
		typeof source.exclude_annual_sales_report ===
		'boolean'
	) {

		normalized.include_sales_report =
			!source.exclude_annual_sales_report;

	} else {

		normalized.include_sales_report =
			!isYes(
				source.exclude_annual_sales_report
			);
	}


	/**
	 * ========================================================
	 * 4. WORD-FRIENDLY DISPLAY VALUES
	 * ========================================================
	 */


	normalized.suite_sf_formatted =
		formatSquareFeet(source.suite_sf);


	normalized.security_deposit_amount_formatted =
		formatCurrency(
			source.security_deposit_amount
		);


	normalized.termination_fee_formatted =
		formatCurrency(
			source.termination_fee
		);


	normalized.rentAmountNewOptions_perMonth_formatted =
		formatCurrency(
			source.rentAmountNewOptions_perMonth
		);


	normalized.rentAmountNewOptions_secDeposit_formatted =
		formatCurrency(
			source.rentAmountNewOptions_secDeposit
		);


	normalized.firstMonth_CIT_formatted =
		formatCurrency(
			source['1stMonth+CIT']
		);


	/**
	 * ========================================================
	 * 5. DATE NORMALIZATION
	 * ========================================================
	 *
	 * Convert Excel serial dates back into ordinary date
	 * strings while still retaining formatted versions.
	 */


	/**
	 * Raw normalized dates
	 *
	 * Example:
	 * 46266 -> 9/1/2026
	 */

	normalized.newLRA_leaseStartDate =
		normalizeRawDate(
			source.newLRA_leaseStartDate
		);


	normalized.newLRA_leaseDeliveryDate =
		normalizeRawDate(
			source.newLRA_leaseDeliveryDate
		);


	normalized.newLRA_leaseEndDate =
		normalizeRawDate(
			source.newLRA_leaseEndDate
		);


	normalized.newLRA_RCD =
		normalizeRawDate(
			source.newLRA_RCD
		);


	normalized.termination_effectiveDate =
		normalizeRawDate(
			source.termination_effectiveDate
		);


	/**
	 * --------------------------------------------------------
	 * LEASE START DATE
	 * --------------------------------------------------------
	 */

	normalized.newLRA_leaseStartDate_formatted =
		formatDateLong(
			source.newLRA_leaseStartDate
		);


	normalized.newLRA_leaseStartDate_day =
		formatOrdinalDay(
			source.newLRA_leaseStartDate
		);


	normalized.newLRA_leaseStartDate_monthYear =
		formatMonthYear(
			source.newLRA_leaseStartDate
		);


	/**
	 * --------------------------------------------------------
	 * LEASE DELIVERY DATE
	 * --------------------------------------------------------
	 */

	normalized.newLRA_leaseDeliveryDate_formatted =
		formatDateLong(
			source.newLRA_leaseDeliveryDate
		);


	normalized.newLRA_leaseDeliveryDate_day =
		formatOrdinalDay(
			source.newLRA_leaseDeliveryDate
		);


	normalized.newLRA_leaseDeliveryDate_monthYear =
		formatMonthYear(
			source.newLRA_leaseDeliveryDate
		);


	/**
	 * --------------------------------------------------------
	 * LEASE END DATE
	 * --------------------------------------------------------
	 */

	normalized.newLRA_leaseEndDate_formatted =
		formatDateLong(
			source.newLRA_leaseEndDate
		);


	normalized.newLRA_leaseEndDate_day =
		formatOrdinalDay(
			source.newLRA_leaseEndDate
		);


	normalized.newLRA_leaseEndDate_monthYear =
		formatMonthYear(
			source.newLRA_leaseEndDate
		);


	/**
	 * --------------------------------------------------------
	 * RCD
	 * --------------------------------------------------------
	 */

	normalized.newLRA_RCD_formatted =
		formatDateLong(
			source.newLRA_RCD
		);


	normalized.newLRA_RCD_day =
		formatOrdinalDay(
			source.newLRA_RCD
		);


	normalized.newLRA_RCD_monthYear =
		formatMonthYear(
			source.newLRA_RCD
		);


	/**
	 * --------------------------------------------------------
	 * TERMINATION EFFECTIVE DATE
	 * --------------------------------------------------------
	 */

	normalized.termination_effectiveDate_formatted =
		formatDateLong(
			source.termination_effectiveDate
		);


	normalized.termination_effectiveDate_day =
		formatOrdinalDay(
			source.termination_effectiveDate
		);


	normalized.termination_effectiveDate_monthYear =
		formatMonthYear(
			source.termination_effectiveDate
		);


	/**
	 * ========================================================
	 * 6. REMOVE DEVELOPMENT-ONLY FIELDS
	 * ========================================================
	 */

	delete normalized[
		'XXX For Update Field XXX'
	];


	/**
	 * ========================================================
	 * 7. TEMPLATE METADATA
	 * ========================================================
	 */

	normalized.template_meta = {

		document_type:
			source.doc_requested ?? null,


		lease_id:
			source.lease_id ?? null,


		suite_id:
			source.suite_id ?? null,


		whole_term_rows:
			wholeTerm_Calc.length,


		has_option:
			normalized.has_option,


		include_waived_rent:
			normalized.include_waived_rent,
	};


	/**
	 * ========================================================
	 * RETURN NORMALIZED ITEM
	 * ========================================================
	 */

	return {

		json: normalized,


		/**
		 * Preserve n8n item linking when using:
		 * Run Once for All Items
		 */
		pairedItem: {
			item: itemIndex,
		},
	};
});

let salesReport_clause = '';

const excludeAnnualSalesReport =
	$('Data Normalization').item.json.exclude_annual_sales_report;


/**
 * Handle either:
 * true
 * "true"
 */
const isExcluded =
	excludeAnnualSalesReport === true ||
	String(excludeAnnualSalesReport)
		.trim()
		.toLowerCase() === 'true';


if (isExcluded) {

	salesReport_clause =
		'INTENTIONALLY OMITTED.';

} else {

	salesReport_clause =
		'Lessee shall submit to Lessor on or before February 28th of each year a written statement signed by Lessee and certified to be true and correct, showing the amount of Gross Sales from the Premises during the preceding calendar year. The term "Gross Sales" is hereby defined to mean all sales by Lessee and all licensees, concessionaires and sublessees of Lessee, from all business conducted from the Premises, whether such sales are evidenced by check, credit charge account, and exchange or otherwise. Gross Sales shall include, but not be limited to, the amount received from the sale of goods and from the performance of services at the Premises, including all orders taken or received at the Premises and sales completed by delivery at the Premises.';
}


return {
	json: {
		salesReport_clause,
	},
};

const source = $('Data Normalization').item.json;


/**
 * ============================================================
 * HELPERS
 * ============================================================
 */

function isBlank(value) {
	return (
		value === null ||
		value === undefined ||
		(typeof value === 'string' && value.trim() === '')
	);
}


function isYes(value) {
	if (typeof value === 'boolean') {
		return value;
	}

	if (isBlank(value)) {
		return false;
	}

	return ['YES', 'Y', 'TRUE', '1'].includes(
		String(value).trim().toUpperCase()
	);
}


/**
 * Parse M/D/YYYY or MM/DD/YYYY.
 */
function parseDate(value) {
	if (isBlank(value)) {
		return null;
	}

	const raw = String(value).trim();

	const match =
		raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);

	if (!match) {
		return null;
	}

	const month = Number(match[1]);
	const day = Number(match[2]);
	const year = Number(match[3]);

	const date =
		new Date(Date.UTC(year, month - 1, day));

	if (Number.isNaN(date.getTime())) {
		return null;
	}

	return date;
}


/**
 * Format as MM/DD/YYYY.
 */
function formatDateShort(date) {
	if (
		!(date instanceof Date) ||
		Number.isNaN(date.getTime())
	) {
		return '';
	}

	const month =
		String(date.getUTCMonth() + 1)
			.padStart(2, '0');

	const day =
		String(date.getUTCDate())
			.padStart(2, '0');

	const year =
		date.getUTCFullYear();

	return `${month}/${day}/${year}`;
}


/**
 * ============================================================
 * DEFAULT OUTPUTS
 * ============================================================
 */

let waivedMonthly_amount = '';
let waivedRent_Content = '';


/**
 * ============================================================
 * WAIVED RENT LOGIC
 * ============================================================
 */

if (isYes(source.lastNote_Waived_Rent)) {

	const leaseStartDate =
		parseDate(source.newLRA_leaseStartDate);

	const rentCommencementDate =
		parseDate(source.newLRA_RCD);

	const wholeTermCalc =
		Array.isArray(source.wholeTerm_Calc)
			? source.wholeTerm_Calc
			: [];


	/**
	 * Only continue if:
	 * - Lease Start Date exists
	 * - RCD exists
	 * - At least one rent row exists
	 */
	if (
		leaseStartDate &&
		rentCommencementDate &&
		wholeTermCalc.length > 0
	) {

		/**
		 * Waived rent starts on Lease Start Date.
		 */
		const waivedStartDate =
			leaseStartDate;


		/**
		 * Waived rent ends one day before RCD.
		 */
		const waivedEndDate =
			new Date(rentCommencementDate.getTime());

		waivedEndDate.setUTCDate(
			waivedEndDate.getUTCDate() - 1
		);


		/**
		 * First paid rent row.
		 */
		const firstPaidRentRow =
			wholeTermCalc.find(row => {

				const monthlyRent =
					Number(row.monthly_base_rent);

				return (
					Number.isFinite(monthlyRent) &&
					monthlyRent > 0
				);
			});


		if (firstPaidRentRow) {

			waivedMonthly_amount =
				firstPaidRentRow
					.monthly_base_rent_formatted ?? '';


			const yearStartDate =
				formatDateShort(waivedStartDate);

			const yearEndDate =
				formatDateShort(waivedEndDate);


			waivedRent_Content =
				`The base Monthly Rent in the amount of ${waivedMonthly_amount} per month and Additional Charges (Operating Expenses, Property Taxes and Insurance) in the estimated amount of ${source.rentAmountNewOptions_perMonth_formatted} per month are conditionally waived for the period from ${yearStartDate} through ${yearEndDate}. Lessee acknowledges that the conditionally waived base Monthly Rent and Additional Charges shall immediately become due and payable to Lessor in the event of any monetary default by Lessee under the Lease beyond applicable notice and opportunity to cure.`;
		}
	}
}


/**
 * ============================================================
 * RETURN
 * ============================================================
 */

return {
	json: {
		waivedMonthly_amount,
		waivedRent_Content,
	},
};

const brokerStatus = String($json.lastNote_BrokerStatus ?? '')
	.trim();

const halpernBroker = String($json.halpern_broker ?? '')
	.trim()
	.toUpperCase();

const tenantBroker = String($json.tenant_broker ?? '')
	.trim()
	.toUpperCase();


let brokerPart1 = '';
let brokerName1 = '';
let brokerPart2 = '';
let brokerName2 = '';
let brokerPart3 = '';


switch (brokerStatus) {

	/**
	 * ========================================================
	 * NO BROKERS
	 * ========================================================
	 */
	case 'None':

		brokerPart1 =
			'Lessor and Lessee hereby represent to each other that in connection with this Lease, neither party has dealt with any real estate broker, agent, or other person or entity which could or may claim that it is entitled to any brokerage commission, fee, or similar compensation. Each party shall indemnify, defend, protect and hold harmless the other, its agents and legal representatives, against any claim for such fee, commission, or other compensation claimed by any broker or agent utilized by such party with respect to this Lease.';

		break;


	/**
	 * ========================================================
	 * BOTH BROKERS
	 *
	 * Name 1 = Halpern broker
	 * Name 2 = Tenant broker
	 * ========================================================
	 */
	case 'Both':

		brokerPart1 =
			'Lessor and Lessee hereby represent to each other that in connection with this Lease, neither party has dealt with any real estate broker, agent, or other person or entity which could or may claim that it is entitled to any brokerage commission, fee, or similar compensation other than ';

		brokerName1 =
			halpernBroker;

		brokerPart2 =
			', who has represented Lessor, and ';

		brokerName2 =
			tenantBroker;

		brokerPart3 =
			' who has represented Lessee in this transaction and will be compensated by Lessor under a separate agreement. Each party shall indemnify, defend, protect and hold harmless the other, its agents and legal representatives, against any claim for such fee, commission, or other compensation claimed by any other broker or agent utilized by such party with respect to this Lease.';

		break;


	/**
	 * ========================================================
	 * TENANT BROKER ONLY
	 *
	 * Name 1 = Tenant broker
	 * Name 2 = blank
	 * ========================================================
	 */
	case 'T only':

		brokerPart1 =
			'Lessor and Lessee hereby represent to each other that in connection with this Lease, neither party has dealt with any real estate broker, agent, or other person or entity which could or may claim that it is entitled to any brokerage commission, fee, or similar compensation other than ';

		brokerName1 =
			tenantBroker;

		brokerPart2 =
			', who has represented Lessee in this transaction and will be compensated by Lessor under a separate agreement. Each party shall indemnify, defend, protect and hold harmless the other, its agents and legal representatives, against any claim for such fee, commission, or other compensation claimed by any other broker or agent utilized by such party with respect to this Lease.';

		break;


	/**
	 * ========================================================
	 * HALPERN BROKER ONLY
	 *
	 * Name 1 = Halpern broker
	 * Name 2 = blank
	 * ========================================================
	 */
	case 'HEI only':

		brokerPart1 =
			'Lessor and Lessee hereby represent to each other that in connection with this Lease, neither party has dealt with any real estate broker, agent, or other person or entity which could or may claim that it is entitled to any brokerage commission, fee, or similar compensation other than ';

		brokerName1 =
			halpernBroker;

		brokerPart2 =
			', who has represented Lessor in this transaction and will be compensated by Lessor under a separate agreement. Each party shall indemnify, defend, protect and hold harmless the other, its agents and legal representatives, against any claim for such fee, commission, or other compensation claimed by any other broker or agent utilized by such party with respect to this Lease.';

		break;


	default:

		throw new Error(
			`Unknown Broker Status: "${brokerStatus}"`
		);
}


return {
	json: {
		brokerPart1,
		brokerName1,
		brokerPart2,
		brokerName2,
		brokerPart3,
	},
};

// ------------------------------------------------------------
// SOURCE DATA
// ------------------------------------------------------------

const data = $('Data Normalization').item.json;

const {
  lastNote_Waived_Rent,
  newLRA_leaseStartDate,
  newLRA_RCD,
  newLRA_leaseEndDate,
  wholeTerm_Calc,
} = data;


// ------------------------------------------------------------
// HELPERS
// ------------------------------------------------------------

function parseDate(value) {
  if (!value) {
    throw new Error(`Missing date value: ${value}`);
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    throw new Error(`Invalid date value: ${value}`);
  }

  return date;
}


function addDays(date, days) {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}


function addYears(date, years) {
  const result = new Date(date);
  result.setFullYear(result.getFullYear() + years);
  return result;
}


function formatDate(date) {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const year = date.getFullYear();

  return `${month}/${day}/${year}`;
}


// ------------------------------------------------------------
// VALIDATE INPUT ARRAY
// ------------------------------------------------------------

if (!Array.isArray(wholeTerm_Calc)) {
  throw new Error(
    `wholeTerm_Calc is not an array. Received: ${JSON.stringify(wholeTerm_Calc)}`
  );
}


// ------------------------------------------------------------
// NORMALIZE WAIVED RENT FLAG
// ------------------------------------------------------------

const waivedRent = String(
  lastNote_Waived_Rent ?? ''
)
  .trim()
  .toUpperCase();


// ------------------------------------------------------------
// NORMALIZE RCD
// ------------------------------------------------------------

const normalizedRCD = String(
  newLRA_RCD ?? ''
)
  .trim()
  .toUpperCase();


// ------------------------------------------------------------
// DETERMINE WHETHER RCD HAS AN ACTUAL VALUE
// ------------------------------------------------------------

const hasActualRCD =
  normalizedRCD !== '' &&
  normalizedRCD !== 'TBD';


// ------------------------------------------------------------
// TABLE VISIBILITY FLAGS
// ------------------------------------------------------------

const showWaivedRentTable = hasActualRCD;
const showNormalRentTable = !hasActualRCD;


// ------------------------------------------------------------
// TABLE HEADERS
// ------------------------------------------------------------

const waiveTableHeader1 =
  hasActualRCD
    ? 'Monthly Base Rent'
    : '';

const waiveTableHeader2 =
  hasActualRCD
    ? 'Annual Base Rent'
    : '';

const waiveTableHeader3 =
  hasActualRCD
    ? 'Beginning Date'
    : '';

const waiveTableHeader4 =
  hasActualRCD
    ? 'End Date'
    : '';


const normalTableHeader1 =
  !hasActualRCD
    ? 'Lease Year'
    : '';

const normalTableHeader2 =
  !hasActualRCD
    ? 'Monthly Base Rent'
    : '';

const normalTableHeader3 =
  !hasActualRCD
    ? 'Annual Base Rent'
    : '';


// ------------------------------------------------------------
// NO ACTUAL RCD
//
// Use normal table.
// ------------------------------------------------------------

if (!hasActualRCD) {
  return {
      json: {
        rentTable: wholeTerm_Calc,

        normalRentTable: wholeTerm_Calc,
        waivedRentTable: [],

        showWaivedRentTable: false,
        showNormalRentTable: true,

        waiveTableHeader1,
        waiveTableHeader2,
        waiveTableHeader3,
        waiveTableHeader4,

        normalTableHeader1,
        normalTableHeader2,
        normalTableHeader3,
      },
    };
}


// ------------------------------------------------------------
// RCD EXISTS, BUT WAIVED RENT IS NOT YES
//
// Preserve original rent table.
// Per your current rule, RCD controls table structure.
// ------------------------------------------------------------

if (waivedRent !== 'YES') {
  return {
      json: {
        rentTable: wholeTerm_Calc,

        normalRentTable: [],
        waivedRentTable: wholeTerm_Calc,

        showWaivedRentTable: true,
        showNormalRentTable: false,

        waiveTableHeader1,
        waiveTableHeader2,
        waiveTableHeader3,
        waiveTableHeader4,

        normalTableHeader1,
        normalTableHeader2,
        normalTableHeader3,
      },
    };
}


// ------------------------------------------------------------
// YES WAIVED RENT + ACTUAL RCD
// ------------------------------------------------------------

if (wholeTerm_Calc.length === 0) {
  throw new Error('wholeTerm_Calc is empty.');
}


// ------------------------------------------------------------
// PARSE DATES
// ------------------------------------------------------------

const leaseStartDate =
  parseDate(newLRA_leaseStartDate);

const rentCommencementDate =
  parseDate(newLRA_RCD);

const leaseEndDate =
  parseDate(newLRA_leaseEndDate);


// ------------------------------------------------------------
// VALIDATE DATES
// ------------------------------------------------------------

if (rentCommencementDate <= leaseStartDate) {
  throw new Error(
    `newLRA_RCD (${newLRA_RCD}) must be after ` +
    `newLRA_leaseStartDate (${newLRA_leaseStartDate}) ` +
    `when waived rent is YES.`
  );
}


if (leaseEndDate < rentCommencementDate) {
  throw new Error(
    `newLRA_leaseEndDate (${newLRA_leaseEndDate}) ` +
    `cannot be before newLRA_RCD (${newLRA_RCD}).`
  );
}


// ------------------------------------------------------------
// BUILD WAIVED RENT TABLE
// ------------------------------------------------------------

const output = [];


// ------------------------------------------------------------
// ROW 1
// WAIVED RENT PERIOD
// ------------------------------------------------------------

output.push({
  yearStartDate:
    formatDate(leaseStartDate),

  yearEndDate:
    formatDate(
      addDays(rentCommencementDate, -1)
    ),

  monthly_base_rent: 0,
  annual_base_rent: 0,

  monthly_base_rent_formatted: '$ 0.00',
  annual_base_rent_formatted: '$ 0.00',
});


// ------------------------------------------------------------
// PAID RENT PERIODS
// ------------------------------------------------------------

for (let i = 0; i < wholeTerm_Calc.length; i++) {

  const sourceRentRow = wholeTerm_Calc[i];

  let yearStartDate;
  let yearEndDate;


  // ----------------------------------------------------------
  // FIRST PAID RENT PERIOD
  // ----------------------------------------------------------

  if (i === 0) {

    yearStartDate =
      rentCommencementDate;

    yearEndDate =
      addDays(
        addYears(leaseStartDate, 1),
        -1
      );

  } else {

    // --------------------------------------------------------
    // FOLLOWING LEASE YEARS
    // --------------------------------------------------------

    const previousRow =
      output[output.length - 1];

    const previousEndDate =
      parseDate(previousRow.yearEndDate);

    yearStartDate =
      addDays(previousEndDate, 1);

    yearEndDate =
      addYears(previousEndDate, 1);
  }


  // ----------------------------------------------------------
  // DO NOT EXTEND BEYOND LEASE END DATE
  // ----------------------------------------------------------

  if (yearEndDate > leaseEndDate) {
    yearEndDate = leaseEndDate;
  }


  // ----------------------------------------------------------
  // ADD RENDER ROW
  // ----------------------------------------------------------

  output.push({
    yearStartDate:
      formatDate(yearStartDate),

    yearEndDate:
      formatDate(yearEndDate),

    monthly_base_rent:
      sourceRentRow.monthly_base_rent,

    annual_base_rent:
      sourceRentRow.annual_base_rent,

    monthly_base_rent_formatted:
      sourceRentRow.monthly_base_rent_formatted,

    annual_base_rent_formatted:
      sourceRentRow.annual_base_rent_formatted,
  });


  // ----------------------------------------------------------
  // STOP AT LEASE END
  // ----------------------------------------------------------

  if (
    yearEndDate.getTime() >=
    leaseEndDate.getTime()
  ) {
    break;
  }
}


// ------------------------------------------------------------
// FINAL VALIDATION
// ------------------------------------------------------------

const finalRow =
  output[output.length - 1];

const finalEndDate =
  parseDate(finalRow.yearEndDate);


if (
  finalEndDate.getTime() !==
  leaseEndDate.getTime()
) {
  throw new Error(
    `Generated rent schedule ended on ` +
    `${formatDate(finalEndDate)}, ` +
    `but lease ends on ` +
    `${formatDate(leaseEndDate)}.`
  );
}


// ------------------------------------------------------------
// FINAL RESPONSE
// ------------------------------------------------------------

return {
    json: {
      rentTable: output,

      normalRentTable: [],
      waivedRentTable: output,

      showWaivedRentTable: true,
      showNormalRentTable: false,

      waiveTableHeader1,
      waiveTableHeader2,
      waiveTableHeader3,
      waiveTableHeader4,

      normalTableHeader1,
      normalTableHeader2,
      normalTableHeader3,
    },
  };

// ------------------------------------------------------------
// SOURCE DATA
// ------------------------------------------------------------

const data = $('Data Normalization').first().json;

const {
  autoInsurance_vehicle_parked_onsite,
  childElder_abuse,
  dram_shop,
} = data;


// ------------------------------------------------------------
// HELPER
//
// Handles:
// true / false
// "true" / "false"
// "yes" / "no"
// 1 / 0
// ------------------------------------------------------------

function isTrue(value) {
  if (value === true || value === 1) {
    return true;
  }

  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();

    return (
      normalized === 'true' ||
      normalized === 'yes' ||
      normalized === '1'
    );
  }

  return false;
}


// ------------------------------------------------------------
// AUTOMOBILE LIABILITY
// ------------------------------------------------------------

const lesseeAutomobileInsurance_clause =
  isTrue(autoInsurance_vehicle_parked_onsite)
    ? '$1,000,000 Automobile Liability insurance for Owned, Hired, and Non-Owned vehicles;'
    : 'INTENTIONALLY OMITTED;';


// ------------------------------------------------------------
// DRAM SHOP
// ------------------------------------------------------------

const lesseeDramInsurance_clause =
  isTrue(dram_shop)
    ? 'so-called “dram shop” insurance in an amount not less than $1,000,000 per occurrence if Lessee\'s permitted use allows the sale of beer, wine and/or alcohol in the Premises;'
    : 'INTENTIONALLY OMITTED;';


// ------------------------------------------------------------
// CHILD / ELDER ABUSE
// ------------------------------------------------------------

const lesseeChildElderInsurance_clause =
  isTrue(childElder_abuse)
    ? 'Sexual Abuse and Molestation or Sexual Molestation Liability insurance coverage in an amount not less than $1,000,000 per occurrence if Lessee’s permitted use includes interactions with children or the elderly;'
    : 'INTENTIONALLY OMITTED;';


// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return {
    json: {
      lesseeAutomobileInsurance_clause,
      lesseeDramInsurance_clause,
      lesseeChildElderInsurance_clause,
    },
  };

const source = $('Data Normalization').item.json;


/**
 * ============================================================
 * HELPERS
 * ============================================================
 */

function isBlank(value) {
	return (
		value === null ||
		value === undefined ||
		(typeof value === 'string' && value.trim() === '')
	);
}


function isYes(value) {
	if (typeof value === 'boolean') {
		return value;
	}

	if (isBlank(value)) {
		return false;
	}

	return ['YES', 'Y', 'TRUE', '1'].includes(
		String(value).trim().toUpperCase()
	);
}


function isTBDorBlank(value) {
	if (isBlank(value)) {
		return true;
	}

	return String(value)
		.trim()
		.toUpperCase() === 'TBD';
}


function isNonZeroNumber(value) {
	if (isBlank(value)) {
		return false;
	}

	const number = Number(value);

	return (
		Number.isFinite(number) &&
		number !== 0
	);
}


function formatCurrency(value) {
	if (isBlank(value)) {
		return '';
	}

	const number = Number(value);

	if (!Number.isFinite(number)) {
		return '';
	}

	return number.toLocaleString('en-US', {
		style: 'currency',
		currency: 'USD',
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	});
}


/**
 * Convert integer to English word.
 *
 * Supports the range we reasonably need for lease terms.
 */
function numberToWords(value) {
	const number = Number(value);

	if (!Number.isInteger(number) || number < 0) {
		return '';
	}

	const ones = [
		'ZERO',
		'ONE',
		'TWO',
		'THREE',
		'FOUR',
		'FIVE',
		'SIX',
		'SEVEN',
		'EIGHT',
		'NINE',
		'TEN',
		'ELEVEN',
		'TWELVE',
		'THIRTEEN',
		'FOURTEEN',
		'FIFTEEN',
		'SIXTEEN',
		'SEVENTEEN',
		'EIGHTEEN',
		'NINETEEN',
	];

	const tens = [
		'',
		'',
		'TWENTY',
		'THIRTY',
		'FORTY',
		'FIFTY',
		'SIXTY',
		'SEVENTY',
		'EIGHTY',
		'NINETY',
	];

	if (number < 20) {
		return ones[number];
	}

	if (number < 100) {
		const ten = Math.floor(number / 10);
		const remainder = number % 10;

		return remainder === 0
			? tens[ten]
			: `${tens[ten]}-${ones[remainder]}`;
	}

	return String(number);
}


/**
 * ============================================================
 * BUILD ADDENDUM ARRAY
 * ============================================================
 */

const addendums = [];


/**
 * Helper for appending one clause.
 */
function addClause({
	part1 = '',
	bold1 = '',
	part2 = '',
	bold2 = '',
	part3 = '',
	bold3 = '',
	part4 = '',
}) {

	addendums.push({
		number_sequence: addendums.length + 1,

		part1,
		bold1,
		part2,
		bold2,
		part3,
		bold3,
		part4,
	});
}

/**
 * ============================================================
 * 1. TBD / BLANK RCD CLAUSES
 * ============================================================
 *
 * Add only when newLRA_RCD is TBD, null, undefined, or blank.
 */

if (isTBDorBlank(source.newLRA_RCD)) {

	const leaseTermYears =
		Number(source.newLRA_leaseTermYrs);

	const leaseTermYearsWord =
		numberToWords(leaseTermYears);


	addClause({
      part1: ``,
      bold1: `LEASE TERM: ${leaseTermYearsWord} (${source.newLRA_leaseTermYrs})`,
      part2: ` years following the Rent Commencement Date. The first "Lease Year" shall mean the period beginning on the Rental Commencement Date and expiring on the last day of the twelfth full calendar month thereafter including any partial calendar month occurring at the beginning of the Lease term. Any subsequent "Lease Year" shall mean a period of twelve (12) calendar months commencing on the first day of the month following the expiration of the first "Lease Year" or any anniversary thereof.`,
      bold2: ``,
      part3: ``,
      bold3: ``,
      part4: ``,
      });


	addClause({
      part1: ``,
      bold1: `LEASE COMMENCEMENT DATE:`,
      part2: ` The Lease Commencement Date (“LCD”) shall occur upon full execution of the Lease.`,
      bold2: ``,
      part3: ``,
      bold3: ``,
      part4: ``
    });


	addClause({
      part1: ``,
      bold1: `POSSESSION DATE:`,
      part2: ` Possession shall occur upon the date Lessor delivers possession of the Premises to Lessee.`,
      bold2: ``,
      part3: ``,
      bold3: ``,
      part4: ``
    });
}


/**
 * ============================================================
 * 2. DEFAULT ADDENDUM CLAUSES
 * ============================================================
 */

addClause({
      part1: `Lessee agrees to accept the Premises in “As Is” condition.`,
      bold1: ``,
      part2: ``,
      bold2: ``,
      part3: ``,
      bold3: ``,
      part4: ``
});


addClause({
      part1: ``,
      bold1: `LESSOR’S WORK:`,
      part2: ` Lessor agrees to deliver the Premises in “AS-IS” condition, with all HVAC, Plumbing and Electrical systems in good working order.`,
      bold2: ``,
      part3: ``,
      bold3: ``,
      part4: ``
});


addClause({
      part1: `Lessee shall provide a valid Certificate of Insurance naming `,
      bold1: `HALPERN ENTERPRISES, INC, AND ITS SUBSIDIARIES`,
      part2: ` as an additional insured party under the policy to Lessor before taking Possession of the Premises.`,
      bold2: ``,
      part3: ``,
      bold3: ``,
      part4: ``
});


/**
 * ============================================================
 * 3. DRAM SHOP
 * ============================================================
 */

if (!isYes(source.dram_shop)) {

	addClause({
      part1: `No alcohol shall be provided, sold or served for onsite consumption.`,
      bold1: ``,
      part2: ``,
      bold2: ``,
      part3: ``,
      bold3: ``,
      part4: ``
    });
}


/**
 * ============================================================
 * 4. THIRD-PARTY UTILITY METERS
 * ============================================================
 */

if (isYes(source['3rdParty_read_utility_meters'])) {

	addClause({
      part1: ``,
      bold1: `UTILITY METERS:`,
      part2: ` The water and sewer meters shall be read by a third party company, and invoices for Lessee’s share shall be created by such third-party company. Lessee’s share of the water and sewer bill shall be added to the rental due for the Premises as Additional Rent.`,
      bold2: ``,
      part3: ``,
      bold3: ``,
      part4: ``
    });
}


/**
 * ============================================================
 * 5. LESSEE IMPROVEMENT ALLOWANCE
 * ============================================================
 *
 * Include only if BOTH:
 *
 * rentAmountNewOptions_PSF != 0/null
 * AND
 * rentAmountNewOptions_PSF$Amount != 0/null
 */

const hasImprovementAllowancePSF =
	isNonZeroNumber(
		source.rentAmountNewOptions_PSF
	);

const hasImprovementAllowanceAmount =
	isNonZeroNumber(
		source['rentAmountNewOptions_PSF$Amount']
	);


if (
	hasImprovementAllowancePSF &&
	hasImprovementAllowanceAmount
) {

	const allowanceAmount =
		formatCurrency(
			source['rentAmountNewOptions_PSF$Amount']
		);


	addClause({
      part1: ``,
      bold1: `LESSEE IMPROVEMENT ALLOWANCE:`,
      part2: ` Lessor agrees to contribute `,
      bold2: `${allowanceAmount}`,
      part3: ` toward Lessee’s interior improvements to the Premises. All improvements must be approved by the Lessor in writing prior to construction and must be completed in a good and workmanlike manner using Lessor’s preferred professional licensed contractors. Lessee is responsible for any and all permits. Allowance is payable within 30 days after Lessee opens for business in the Premises and upon Lessee: (i) completing all improvements, (ii) providing an affidavit from Lessee’s general contractor listing all sub-contractors and suppliers providing labor and materials for the interior improvements, (iii) providing Final Unconditional Lien Waivers from the general contractor and every party listed on the affidavit to Lessor indicating that they have all been paid in full, (iv) providing Lessor with the Certificate of Insurance and Certificate of Occupancy, (v) providing Lessor with a W-9, and (vi) paying second month full Base rent and Additional Charges.`,
      bold3: ``,
      part4: ``
            });
}


/**
 * ============================================================
 * RETURN
 * ============================================================
 */

return {
		json: {
			addendums,
			addendum_count: addendums.length,
		},
	};

parameters.jsonBody:
={
  "message": {
    "subject": "You have a New Lease Document Generated - {{ $('Data Normalization').item.json.lessee_legal_name }}",
