parameters.jsCode:
const intendedFileName = String(
	$('Intended File Name').item.json.intended_fileName ?? ''
).trim();


const folderItems =
	$('Get All Items in Generated Leases Folder').item.json.value ?? [];


const existingNames = new Set(
	folderItems
		.map(item =>
			String(item.name ?? '')
				.trim()
				.toLowerCase()
		)
		.filter(Boolean)
);


const lastDotIndex = intendedFileName.lastIndexOf('.');

const baseName =
	lastDotIndex > 0
		? intendedFileName.slice(0, lastDotIndex)
		: intendedFileName;

const extension =
	lastDotIndex > 0
		? intendedFileName.slice(lastDotIndex)
		: '';


let finalFileName = intendedFileName;
let copyNumber = 0;


while (
	existingNames.has(
		finalFileName.toLowerCase()
	)
) {
	copyNumber++;

	finalFileName =
		`${baseName} Copy${copyNumber}${extension}`;
}


return {
	json: {
		...$json,
		intended_fileName: intendedFileName,
		finalFileName,
		fileNameWasDuplicate: copyNumber > 0,
		copyNumber,
	},

	binary: {
		generated_doc:
			$('Generate LSE Document').item.binary.generated_doc,
	},
};
